<script setup lang="ts">
import{computed,nextTick,onBeforeUnmount,onMounted,shallowRef,useTemplateRef,watch}from"vue";import{X}from"lucide-vue-next";import SistemaForm from"./SistemaForm.vue";import SistemaRelatedOils from"./SistemaRelatedOils.vue";import SistemaEquipmentTypes from"./SistemaEquipmentTypes.vue";import SistemaImpactSummary from"./SistemaImpactSummary.vue";import type{CatalogoSistemaEditorMode,CatalogoSistemaFieldErrors,CatalogoSistemaGuardarInput,CatalogoSistemaItem}from"@/stores/dbequipos/engrase/catalogo/sistemasCatalogo.types";
const props=defineProps<{open:boolean;mode:CatalogoSistemaEditorMode;item:CatalogoSistemaItem|null;draft:CatalogoSistemaGuardarInput|null;hasChanges:boolean;canSubmit:boolean;saving:boolean;fieldErrors:CatalogoSistemaFieldErrors;saveError?:string|null}>();const emit=defineEmits<{updateDraft:[draft:CatalogoSistemaGuardarInput];requestClose:[];cancel:[];submit:[];blurName:[]}>();const panel=useTemplateRef<HTMLElement>("panel");const desktop=shallowRef(false);const title=computed(()=>props.mode==="crear"?"Nuevo sistema":"Detalles");const action=computed(()=>props.mode==="crear"?"Crear sistema":"Guardar cambios");let media:MediaQueryList|null=null;let overflow="";
function viewport(e?:MediaQueryListEvent){desktop.value=e?.matches??media?.matches??false;document.body.style.overflow=props.open&&!desktop.value?"hidden":overflow}function keydown(e:KeyboardEvent){if(!props.open)return;if(e.key==="Escape"){if(!props.saving){e.preventDefault();emit("requestClose")}return}if(e.key!=="Tab"||desktop.value||!panel.value)return;const controls=Array.from(panel.value.querySelectorAll<HTMLElement>("button:not([disabled]),input:not([disabled])"));const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}
onMounted(()=>{overflow=document.body.style.overflow;media=window.matchMedia?.("(min-width:1024px)")??null;media?.addEventListener("change",viewport);viewport();window.addEventListener("keydown",keydown)});onBeforeUnmount(()=>{document.body.style.overflow=overflow;media?.removeEventListener("change",viewport);window.removeEventListener("keydown",keydown)});watch(()=>props.open,async open=>{viewport();if(open){await nextTick();panel.value?.querySelector<HTMLElement>("h2")?.focus()}});watch(()=>props.fieldErrors.nombre,async error=>{if(error){await nextTick();panel.value?.querySelector<HTMLElement>('[aria-invalid="true"]')?.focus()}});
