<template><Teleport to="body"><div class="fixed inset-0 z-50" :class="open?'pointer-events-auto lg:pointer-events-none':'pointer-events-none'" @click.self="!saving&&emit('requestClose')"><Transition name="system-scrim"><div v-if="open" class="absolute inset-0 bg-main-dark/50 lg:hidden"/></Transition><Transition name="system-panel"><aside v-if="open" ref="panel" class="pointer-events-auto absolute inset-0 flex flex-col border-l border-gray-200 bg-white shadow-xl sm:left-auto sm:right-0 sm:w-[min(420px,100vw)] lg:bottom-0 lg:left-auto lg:right-0 lg:top-[7.4rem] lg:w-[clamp(340px,30vw,420px)]" :role="desktop?undefined:'dialog'" :aria-modal="desktop?undefined:'true'" aria-labelledby="system-drawer-title" :aria-busy="saving"><header class="sticky top-0 z-10 flex min-h-14 items-center justify-between border-b border-gray-200 bg-white px-4"><h2 id="system-drawer-title" tabindex="-1" class="text-base font-bold text-main">{{ title }}</h2><button type="button" class="grid min-h-11 min-w-11 place-items-center rounded-md" :class="saving?'cursor-not-allowed opacity-50':'cursor-pointer hover:bg-gray-100'" :disabled="saving" aria-label="Cerrar detalles" @click="emit('requestClose')"><X class="h-4 w-4"/></button></header><div v-if="draft" class="flex-1 space-y-6 overflow-y-auto p-4 pb-24"><div v-if="saveError" class="rounded-md border border-danger/30 bg-danger-bg p-3 text-xs text-danger" role="alert">{{ saveError }}</div><SistemaForm :draft="draft" :errors="fieldErrors" :disabled="saving" @update-draft="emit('updateDraft',$event)" @blur-name="emit('blurName')"/><template v-if="mode==='editar'&&item"><hr class="border-gray-200"/><SistemaRelatedOils :items="item.aceites"/><SistemaEquipmentTypes :items="item.impacto.tiposEquipo"/><SistemaImpactSummary :impacto="item.impacto"/></template><p v-else class="rounded-md bg-gray-50 p-3 text-xs text-gray-500">Los aceites y equipos relacionados se agregan desde la edición del equipo.</p></div><footer class="sticky bottom-0 mt-auto grid grid-c